urlset:
{{- range .Data.Pages -}}
    {{- if or .IsHome .IsPage (and .IsSection (eq .Section "posts")) -}}

            {{ .Permalink }}
            {{- if not .Lastmod.IsZero }}
                {{ .Lastmod.Format "2006-01-02T15:04:05-07:00" }}
            {{- end }}
            {{- if .IsTranslated -}}
                {{- range .AllTranslations }}

                {{- end }}
                {{- $defaultURL := .Site.Home.Permalink -}}
                {{- range .AllTranslations -}}
                    {{- if eq .Language.Lang "en" -}}
                        {{- $defaultURL = .Permalink -}}
                    {{- end -}}
                {{- end }}

            {{- end }}

    {{- end -}}
{{- end }}
